<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getEmail returns null on a freshly created holder.
     */
    public function testEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isEmailAssigned());
        $this->assertNull($holder->getEmail());
    }
}
class ImplWithUserInvitationEmailAttributeHolderUnitTest
{
    use UserInvitationEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultEmail();
    }
}
